import functools
import warnings


def cache_result(fn):
    cache = {}

    @functools.wraps(fn)
    def wrapper(*args):
        if args not in cache:
            cache[args] = fn(*args)
        return cache[args]

    wrapper.cache = cache
    return wrapper


def require_auth(role):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            user = kwargs.get("user")
            if not user or user.get("role") != role:
                raise PermissionError(f"Requires role: {role}")
            return fn(*args, **kwargs)
        return wrapper
    return decorator


def deprecated(message):
    def decorator(fn):
        warned = False

        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            nonlocal warned
            if not warned:
                warnings.warn(f"{fn.__name__}: {message}", DeprecationWarning, stacklevel=2)
                warned = True
            return fn(*args, **kwargs)
        return wrapper
    return decorator
